            let mut state = states
                .into_iter()
                .next()
                .expect("replay control group is non-empty");
            state.live_order = live_order;
            state.conditional_variants = conditional_variants;
            if let Some(auth) = lexical {
                lexical_boundary::check(
                    function,
                    auth,
                    block_id,
                    &state,
                    storage,
                    &storage_regions,
                    leaves,
                    budget,
                )?;
