    let mut values=map_new<i64,i64>(2usize);
    let mut keys=set_new<i64>(2usize);
    let mut index=0;
    while index < 2 {
        values=map_set<i64,i64>(values,index,index);
        keys=set_insert<i64>(keys,index);
        index=index+1;
