                limit,
                None,
            );
            assert_eq!(result.0, limit == full.2);
            assert_eq!(result.3, limit != full.2);
            assert_eq!(result.4.is_some(), limit != full.2);
            if result.0 {
                assert_eq!(result.2, full.2);
            }
        }
    }
