            let cost = (
                work - budget.remaining,
                bytes - crate::bounded_output::active_remaining().unwrap(),
                crate::test_allocation_observer::current_metrics().allocated - heap,
            );
            drop(removed);
            drop(budget);
            cost
        })
    });
    assert!(
        !refused
            && !allocation.invalid
            && allocation.live == 0
            && allocation.allocated == allocation.freed
    );
    cost
}

