            if id == "core.array-u8.as-slice" && index == 0 {
                assert!(param["type_id"].is_null());
                assert_eq!(param["type_family"], "array_u8_any_length");
            } else {
                assert!(param["type_id"].is_string());
                assert!(param["type_family"].is_null());
